"""35 Rust tasks emphasizing explicit ownership and error contracts."""
from catalog_support import Book
from languages_common import program, require_count


def build_all():
    b=Book("rust","Rust stable 1.75+, edition 2021",["https://doc.rust-lang.org/book/", "https://doc.rust-lang.org/std/"],"Toolchain Rust tramite rustup: rustc e cargo nel PATH. Gli esempi usano soltanto std; nessuna crate da scaricare.")
    def add(title,desc,body,expected,tags,definitions="",command=None):
        source=definitions+"\nfn main() -> Result<(), Box<dyn std::error::Error>> {\n"+body+"\nOk(())\n}\n"
        program(b,title,desc,source,filename="main.rs",command=command or "rustc --edition=2021 main.rs -o demo.exe\n.\\demo.exe",expected=expected,tags=tags.split(),error="Il borrow checker segnala riferimenti o mutazioni non validi: correggere la proprietà dei dati invece di introdurre unsafe per aggirarlo.")
    add("Copiare esplicitamente una String", "Mantiene disponibili due proprietari indipendenti attraverso clone.",'''let first=String::from("Ada");let second=first.clone();println!("{} {}",first,second);''',"Ada Ada; clone copia i dati heap.","ownership clone string")
    add("Leggere tramite prestito immutabile", "Una funzione riceve una vista &str senza acquisire la String del chiamante.",'''let name=String::from("Ada");println!("{} {}",length(&name),name);''',"3 Ada; length conta byte UTF-8.","borrow reference str", "fn length(value:&str)->usize {value.len()}")
    add("Modificare tramite prestito mutabile", "Concede accesso esclusivo temporaneo e poi riutilizza il proprietario.",'''let mut value=String::from("ciao");append(&mut value);println!("{}",value);''',"ciao!", "mutable borrow reference", "fn append(value:&mut String){value.push('!');}")
    add("Passare una porzione di array come slice", "Descrive un intervallo contiguo senza allocare un altro array.",'''let values=[2,3,5,7];let part=&values[1..3];println!("{:?}",part);''',"[3, 5]; gli indici vengono controllati.","slice array range")
    add("Iterare caratteri Unicode invece di byte", "Distingue la lunghezza in byte dal numero di valori scalari Unicode.",'''let value="Città";println!("{} {}",value.len(),value.chars().count());''',"6 5; chars non equivale alla segmentazione in grafemi.","unicode chars utf8 length")
    add("Dividere e ripulire campi testuali", "Usa iteratori su &str e filtra le porzioni vuote.",'''let fields:Vec<&str>=" a, ,b,c ".split(',').map(str::trim).filter(|part|!part.is_empty()).collect();println!("{:?}",fields);''',"[a,b,c] come stringhe.","split trim filter string")
    add("Analizzare un numero con parse", "Gestisce separatamente successo e messaggio di errore del parser.",'''for text in ["42","abc"]{match text.parse::<i32>(){Ok(value)=>println!("{}",value),Err(_)=>println!("numero non valido")}}''',"42 e numero non valido.","parse result numeric")
    add("Usare un default con Option", "Gestisce assenza esplicita senza puntatori nulli.",'''let found:Option<&str>=None;println!("{}",found.unwrap_or("assente"));''',"assente; unwrap senza controllo provocherebbe panic.","option none default")
    add("Combinare operazioni fallibili con Result", "Trasforma soltanto il successo mantenendo l'errore del parser.",'''let result="21".parse::<i32>().map(|value|value*2);println!("{:?}",result);''',"Ok(42)","result map error")
    add("Propagare errori con l'operatore domanda", "Interrompe la funzione al primo errore preservando un contratto Result.",'''println!("{}",sum_text("2","3")?);''',"5; un input non numerico viene propagato al chiamante.","question operator error propagation", "fn sum_text(a:&str,b:&str)->Result<i32,std::num::ParseIntError>{Ok(a.parse::<i32>()?+b.parse::<i32>()?)}")
    add("Selezionare intervalli con match", "Gestisce fasce numeriche e un caso residuale esplicito.",'''let score=82;let grade=match score{90..=100=>"A",75..=89=>"B",60..=74=>"C",_=>"D"};println!("{}",grade);''',"B", "match range pattern")
    add("Rappresentare eventi con enum e payload", "Mantiene associati variante e dati senza union non controllate.",'''let event=Event::Move{x:2,y:3};match event{Event::Move{x,y}=>println!("{},{}",x,y),Event::Quit=>println!("uscita")};let _quit=Event::Quit;''',"2,3", "enum payload algebraic", "enum Event{Move{x:i32,y:i32},Quit}")
    add("Definire metodi su una struct", "Incapsula un calcolo associato a un record tramite impl.",'''let point=Point{x:3,y:4};println!("{}",point.length_squared());''',"25", "struct impl method", "struct Point{x:i32,y:i32}\nimpl Point{fn length_squared(&self)->i32{self.x*self.x+self.y*self.y}}")
    add("Implementare un trait per formattare un valore", "Definisce un comportamento condiviso indipendente dal layout dell'oggetto.",'''let user=User{name:String::from("Ada")};println!("{}",user.label());''',"Utente Ada", "trait implementation interface", "trait Label{fn label(&self)->String;}\nstruct User{name:String}\nimpl Label for User{fn label(&self)->String{format!(\"Utente {}\",self.name)}}")
    add("Vincolare un parametro generico con un trait", "Accetta tipi diversi soltanto se implementano il comportamento richiesto.",'''print_value(42);print_value("Ada");''',"42 e Ada.","generic trait bound", "fn print_value<T:std::fmt::Display>(value:T){println!(\"{}\",value);}")
    add("Collegare la durata di un risultato ai prestiti", "Annota che la stringa restituita proviene da uno dei due input.",'''let a=String::from("breve");let b=String::from("piu lungo");println!("{}",longest(&a,&b));''',"piu lungo; l'annotazione non estende la vita degli input.","lifetime reference borrow", "fn longest<'a>(a:&'a str,b:&'a str)->&'a str{if a.len()>=b.len(){a}else{b}}")
    add("Trasformare un vector con iteratori", "Deriva i quadrati leggendo gli elementi senza spostare il vector iniziale.",'''let values=vec![2,3,4];let squares:Vec<i32>=values.iter().map(|value|value*value).collect();println!("{:?} {:?}",values,squares);''',"Input [2,3,4] e quadrati [4,9,16].", "iterator map collect vector")
    add("Filtrare e copiare elementi di un vector", "Converte i riferimenti selezionati in valori copiati con copied.",'''let values=vec![1,2,3,4];let even:Vec<i32>=values.iter().copied().filter(|value|value%2==0).collect();println!("{:?}",even);''',"[2,4]", "iterator filter copied")
    add("Ridurre una sequenza con fold", "Definisce l'accumulatore iniziale per gestire anche input vuoti.",'''let product=(1..=5).fold(1,|acc,value|acc*value);println!("{}",product);''',"120", "iterator fold accumulator")
    add("Ordinare record tramite una chiave", "Ordina una sequenza in place in base al campo numerico.",'''let mut rows=vec![("Ada",36),("Luca",28)];rows.sort_by_key(|row|row.1);println!("{:?}",rows);''',"Luca precede Ada.","sort_by_key records vector")
    add("Rimuovere duplicati adiacenti con dedup", "Ordina prima i valori quando si vuole deduplicare l'intero insieme.",'''let mut values=vec![3,1,3,2,1];values.sort();values.dedup();println!("{:?}",values);''',"[1,2,3]; l'ordine originale non è conservato.","dedup vector sorting")
    add("Accumulare frequenze con HashMap entry", "Usa entry per aggiornare conteggi senza una doppia ricerca manuale.",'''let mut counts=std::collections::HashMap::new();for word in ["rosso","blu","rosso"]{*counts.entry(word).or_insert(0)+=1;}println!("{}",counts["rosso"]);''',"2", "hashmap entry frequency")
    add("Calcolare differenze con HashSet", "Ricava elementi presenti soltanto nel primo insieme e ordina l'output per stabilità.",'''use std::collections::HashSet;let a:HashSet<_>=[1,2,3].into_iter().collect();let b:HashSet<_>=[2,4].into_iter().collect();let mut difference:Vec<_>=a.difference(&b).copied().collect();difference.sort();println!("{:?}",difference);''',"[1,3]", "hashset difference set")
    add("Iterare chiavi ordinate con BTreeMap", "Sceglie una mappa ordinata quando l'ordine di lettura è parte del risultato.",'''let map=std::collections::BTreeMap::from([("B",2),("A",1)]);for(key,value)in map{println!("{}:{}",key,value);}''',"A:1 poi B:2.","btreemap ordered map")
    add("Gestire una coda con VecDeque", "Inserisce in coda e consuma dalla testa con Option.",'''let mut queue=std::collections::VecDeque::new();queue.push_back("prima");queue.push_back("seconda");while let Some(item)=queue.pop_front(){println!("{}",item);}''',"prima e seconda.","vecdeque queue fifo")
    add("Estrarre il massimo con BinaryHeap", "Usa una coda di priorità max-heap della libreria standard.",'''let mut heap=std::collections::BinaryHeap::from([2,9,4]);while let Some(value)=heap.pop(){println!("{}",value);}''',"9,4,2; usare Reverse per un min-heap.","binaryheap priority heap")
    add("Abbinare iteratori con zip", "Combina elementi corrispondenti e rende esplicita la terminazione alla sequenza più corta.",'''let names=["Ada","Luca"];let ages=[36,28];for(name,age)in names.iter().zip(ages){println!("{}:{}",name,age);}''',"Ada:36 e Luca:28.","zip iterator pairing")
    add("Trasferire proprietà a un thread", "Usa move per trasferire la String al worker e join per attenderne il risultato.",'''let name=String::from("Ada");let worker=std::thread::spawn(move||format!("Ciao {}",name));println!("{}",worker.join().expect("worker fallito"));''',"Ciao Ada; il proprietario iniziale non può più usare name.","thread move join ownership")
    add("Condividere un contatore con Arc e Mutex", "Associa condivisione della proprietà e mutazione protetta tra thread.",'''use std::sync::{Arc,Mutex};let count=Arc::new(Mutex::new(0));let mut threads=Vec::new();for _ in 0..2{let count=Arc::clone(&count);threads.push(std::thread::spawn(move||{for _ in 0..1000{*count.lock().expect("mutex avvelenato")+=1;}}));}for thread in threads{thread.join().expect("worker fallito");}println!("{}",*count.lock().expect("mutex avvelenato"));''',"2000", "arc mutex concurrency")
    add("Trasmettere dati con un canale mpsc", "Consuma il ricevitore fino alla chiusura del sender trasferito al thread.",'''let(sender,receiver)=std::sync::mpsc::channel();let worker=std::thread::spawn(move||{sender.send(42).expect("ricevitore chiuso");});for value in receiver{println!("{}",value);}worker.join().expect("worker fallito");''',"42 e terminazione del ciclo dopo la distruzione del sender.","channel mpsc producer consumer")
    add("Misurare una durata con Instant", "Usa un orologio monotono e rende il risultato del calcolo osservabile.",'''let start=std::time::Instant::now();let sum:u64=(0..10000).sum();println!("{} {:?}",sum,start.elapsed());''',"49995000 e durata variabile.","instant duration benchmark")
    add("Leggere un file UTF-8 con cleanup esplicito", "Scrive un file temporaneo unico, ne legge il contenuto e lo rimuove.",'''let stamp=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_nanos();let path=std::env::temp_dir().join(format!("catalog-rust-{}-{}.txt",std::process::id(),stamp));std::fs::write(&path,"Città")?;let result=std::fs::read_to_string(&path);std::fs::remove_file(&path)?;println!("{}",result?);''',"Città; il percorso temporaneo usa PID e timestamp.","filesystem utf8 result cleanup")
    add("Definire un errore di dominio", "Implementa Display ed Error per un tipo applicativo convertibile in Box<dyn Error>.",'''let error=DomainError("quantita negativa");println!("{}",error);''',"quantita negativa", "custom error display trait", '''#[derive(Debug)]
struct DomainError(&'static str);
impl std::fmt::Display for DomainError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{write!(f,"{}",self.0)}}
impl std::error::Error for DomainError{}''')
    add("Eseguire test integrati con rustc --test", "Inserisce test nel modulo cfg(test) e li esegue senza Cargo né dipendenze.",'''println!("Compilare anche con --test per eseguire i contratti");''',"Due test: somma corretta e caso vuoto.","test cfg assert rustc",'''fn total(values:&[i32])->i32{values.iter().sum()}
#[cfg(test)]mod tests{use super::*;#[test]fn sums(){assert_eq!(total(&[2,3]),5);}#[test]fn empty(){assert_eq!(total(&[]),0);}}''',command="rustc --edition=2021 --test main.rs -o tests.exe\n.\\tests.exe")
    program(b,"Progetto completo lista attività Rust", "Organizza un dominio con proprietà controllata, moduli separati e test Cargo esclusivamente std.",'''mod board;
use board::Board;
fn main(){let mut board=Board::default();let id=board.add("Studiare Rust").expect("titolo valido");board.complete(id).expect("id presente");for task in board.list(){println!("{} {} {}",task.id,task.title,task.done);}}''',filename="src/main.rs",files={
      "Cargo.toml":'''[package]
name="{{project_name}}"
version="0.1.0"
edition="2021"
[dependencies]''',
      "src/board.rs":'''#[derive(Debug,Clone)]
pub struct Task{pub id:usize,pub title:String,pub done:bool}
#[derive(Default)]pub struct Board{tasks:Vec<Task>}
impl Board{
pub fn add(&mut self,title:&str)->Result<usize,&'static str>{if title.trim().is_empty(){return Err("titolo vuoto");}let id=self.tasks.len()+1;self.tasks.push(Task{id,title:title.trim().to_owned(),done:false});Ok(id)}
pub fn complete(&mut self,id:usize)->Result<(),&'static str>{let task=self.tasks.iter_mut().find(|task|task.id==id).ok_or("task assente")?;task.done=true;Ok(())}
pub fn list(&self)->&[Task]{&self.tasks}
}
#[cfg(test)]mod tests{use super::*;#[test]fn lifecycle(){let mut board=Board::default();let id=board.add("Uno").unwrap();board.complete(id).unwrap();assert!(board.list()[0].done);}#[test]fn invalid(){assert!(Board::default().add(" ").is_err());}}''',
      "README.md":"# Task board Rust\n\nRust stable1.75+, Cargo edition2021, nessuna crate esterna. `cargo test --offline` esegue due test; `cargo run --offline` mostra una attività completata. Lo stato è in memoria e non sopravvive all'avvio. list espone una slice immutabile; i riferimenti non possono sopravvivere alla board. Gli ID non vengono riutilizzati perché il progetto non implementa cancellazioni.\n"},command="cargo test --offline\ncargo run --offline",expected="Due test superati; output 1 Studiare Rust true.",tags=("project","cargo","ownership","module","test"),project=True,section="Progetti completi",parameters=[{"name":"project_name","label":"Nome package Cargo","type":"identifier","default":"catalog_rust_board","required":True}])
    require_count(b,35)


if __name__=="__main__":build_all()
